"""Experimental, explicitly selected factory for public-estimate relationship bargaining.

No default agent imports this module. It targets a code-costed cash package, asks for
committee review when public notes support that route, and closes through the existing
coordinator. Public cost uncertainty is traced, never presented as a reservation price.
"""

import math
from pathlib import Path

from arena_kit.cost import RELATIONSHIP_GOALS, must_haves_ok, total_cost
from arena_kit.docs import standard_terms
from arena_kit.play import latest

from .agent import PackageAgent
from .dossiers import build_one, load_package, supplier_estimate
from .evaluator import eligible_sheets, nonprice
from .relationship import active, ceiling, sensitivity, targets
from .responses import permitted
from .traits import evidence

COMMITTEE_REQUEST = (
    "Could you take this complete price-and-payment proposal to your pricing committee for review, "
    "and let us know whether it can approve these terms?"
)


class RelationshipAgent(PackageAgent):
    version = "RelationshipAgent-public-cash-v1"

    def __init__(self, *, package=None, estimates=None, **kwargs):
        # This factory opts into dossier economics regardless of environment variables.
        # Other case types continue through the normal agent with its normal defaults.
        super().__init__(estimates={}, **kwargs)
        self.public_package = package
        self.injected_estimates = estimates
        self.public_estimates = {}
        self.sensitivity_logged = set()
        self.committee_refs = {}

    @staticmethod
    def _single_relationship(case):
        return (len(case.get("suppliers") or []) == 1
                and case.get("buyer", {}).get("category_goal") in RELATIONSHIP_GOALS)

    def estimates_for(self, case):
        if not self._single_relationship(case):
            return super().estimates_for(case)
        if self.injected_estimates is not None:
            return self.injected_estimates
        cid = case["case_id"]
        if cid not in self.public_estimates:
            sid = case["suppliers"][0]
            try:
                if self.public_package is None:
                    self.public_package = load_package()
                estimate = supplier_estimate(case, sid, self.public_package)
                self.public_estimates[cid] = {sid: estimate} if estimate else {}
            except (FileNotFoundError, ValueError, KeyError) as exc:
                self._log(case, "relationship_unavailable", sid, error_type=type(exc).__name__)
                self.public_estimates[cid] = {}
        return self.public_estimates[cid]

    def _enabled(self, case, threads, sid):
        return self._single_relationship(case) and active(case, self._sup(case, threads, sid))

    def _committee_evidence(self, case, sid):
        key = (case["case_id"], sid)
        if key not in self.committee_refs:
            refs = []
            try:
                if self.public_package is None:
                    self.public_package = load_package()
                dossier = build_one(self.public_package, sid)
                if dossier and "pricing_committee" in dossier.traits:
                    refs = evidence(dossier, "pricing_committee")
            except (FileNotFoundError, ValueError, KeyError):
                pass
            self.committee_refs[key] = refs
        return self.committee_refs[key]

    def _final_counter(self, case, threads, sid, c_alt):
        if self._enabled(case, threads, sid):
            # The coordinator evaluates the standing offer; do not risk it by mixing
            # its price with our faster cash or by accepting an alternative sheet ID.
            return None
        return super()._final_counter(case, threads, sid, c_alt)

    def decide_thread(self, case, threads, sid, c_alt, cap_c=None, why=None):
        if not self._enabled(case, threads, sid):
            return super().decide_thread(case, threads, sid, c_alt, cap_c, why)
        events = threads[sid]
        standard, supplier = standard_terms(events), self._sup(case, threads, sid)
        valid = eligible_sheets(case, events, supplier)
        frontier = targets(case, standard, supplier)
        frontier = [(c, t) for c, t in frontier if permitted(case, t) and must_haves_ok(case, t, standard)]
        if not frontier:
            return {"close": True, "reason": "no legal relationship target"}
        target_cost, target = frontier[0]
        key = (case["case_id"], sid)
        if key not in self.sensitivity_logged:
            self._log(case, "relationship_target", sid, terms=target, c=target_cost,
                      public_cost_ref=supplier.get("cost_ref"),
                      sensitivity=sensitivity(case, target, standard, supplier),
                      interpretation="public estimate uncertainty; not an acceptance prediction or price floor")
            self.sensitivity_logged.add(key)

        ours = self._ours(events)
        # Reconstruct the negotiated package from sent history, including after resume.
        base = {**target, **nonprice(case, ours[0])} if ours else dict(target)
        if not permitted(case, base) or not must_haves_ok(case, base, standard):
            return {"close": True, "reason": "stored relationship package no longer legal"}
        if not valid:
            price = target["unit_price"]
        else:
            standing_cost, _, standing_terms = valid[0]
            if standing_cost <= target_cost + 0.01:
                return {"close": True, "reason": "standing package already at public-estimate minimum"}
            # An equal-cost ceiling is on the rising branch. A cap below the package's
            # minimum has no solution: retain the better standing offer, not a fake price.
            cap = min(standing_cost, c_alt, cap_c if cap_c is not None else math.inf)
            upper = ceiling(case, base, cap, standard, supplier)
            if upper is None:
                return {"close": True, "reason": "standing package beats attainable preserved package"}
            upper = min(upper, standing_terms["unit_price"])
            start = target["unit_price"] if not ours else ours[0]["unit_price"]
            if upper < start:
                # No central-estimate floor is imposed on an executable supplier quote.
                return {"close": True, "reason": "supplier price below uncertain target; use complete closing cost"}
            fraction = min(1.0, len(ours) / max(1, self.rounds))
            price = round(start + (upper - start) * fraction, 2)
            if ours:
                price = min(upper, max(price, ours[-1]["unit_price"]))
        terms = {**base, "unit_price": round(price, 2)}
        if not permitted(case, terms) or not must_haves_ok(case, terms, standard):
            return {"close": True, "reason": "no legal positive relationship proposal"}
        if valid and valid[0][0] <= total_cost(case, terms, standard, supplier) + 0.01:
            return {"close": True, "reason": "standing package cheaper than proposed concession"}
        if ours and terms == ours[-1]:
            return {"close": True, "reason": "relationship concession converged"}
        move = self._offer(case, sid, terms, standard, supplier, c_alt,
                           why or "public relationship minimum and preserved cash package")
        if not any(COMMITTEE_REQUEST in event.get("body", "") for event in events if event.get("from") == "buyer"):
            refs = self._committee_evidence(case, sid)
            if refs:
                move["message"]["body"] += " " + COMMITTEE_REQUEST
                self._log(case, "committee_request", sid, supporting_document_ids=refs,
                          recipient_role=latest(events).get("from"), request=COMMITTEE_REQUEST)
        return move


def configured_agent(trace_dir=None, policy_config=None, **kwargs):
    """Opt-in lab factory: negotiator.relationship_agent:configured_agent."""
    if trace_dir is not None:
        from .trace import Tracer

        kwargs["tracer"] = Tracer(Path(trace_dir))
    if policy_config is not None:
        from .policy import PolicyConfig

        kwargs["policy"] = PolicyConfig.from_dict(policy_config)
    kwargs.setdefault("meso", False)
    kwargs.setdefault("claims", False)
    agent = RelationshipAgent(**kwargs)
    agent.conditional_exchange = True
    return agent

