import hashlib
import json
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Literal

TYPES = {"price_increase", "renewal", "rfq", "bundling", "raw_material", "capacity", "quality"}


@dataclass(frozen=True)
class PolicyConfig:
    version: int = 1
